"use client"

import { useState, useEffect } from "react"
import LoadingScreen from "@/components/loading-screen"
import LoginPage from "@/components/login-page"
import RegisterPage from "@/components/register-page"
import HomePage from "@/components/home-page"
import EdukasiPage from "@/components/edukasi-page"
import { MedicationReminderPage } from "@/components/medication-reminder-page"
import UntukDiriSendiriPage from "@/components/untuk-diri-sendiri-page"
import UntukKeluargaPage from "@/components/untuk-keluarga-page"
import BeritaTBCPage from "@/components/berita-tbc-page"

type PageType =
  | "loading"
  | "login"
  | "register"
  | "home"
  | "edukasi"
  | "jadwal"
  | "untuk-diri-sendiri"
  | "untuk-keluarga"
  | "berita-tbc"

export default function Page() {
  const [currentPage, setCurrentPage] = useState<PageType>("loading")
  const [isAuthenticated, setIsAuthenticated] = useState(false)

  useEffect(() => {
    const checkAuth = () => {
      const currentUser = localStorage.getItem("tbcare_current_user")
      if (currentUser) {
        setIsAuthenticated(true)
        setCurrentPage("home")
      } else {
        setCurrentPage("login")
      }
    }

    // Show loading screen for 2 seconds
    const timer = setTimeout(() => {
      checkAuth()
    }, 2000)

    return () => clearTimeout(timer)
  }, [])

  const handleLogin = () => {
    setIsAuthenticated(true)
    setCurrentPage("home")
  }

  const handleLogout = () => {
    setIsAuthenticated(false)
    setCurrentPage("login")
  }

  const handleNavigate = (page: PageType) => {
    setCurrentPage(page)
  }

  return (
    <>
      {currentPage === "loading" && <LoadingScreen />}
      {currentPage === "login" && <LoginPage onRegister={() => setCurrentPage("register")} onLogin={handleLogin} />}
      {currentPage === "register" && <RegisterPage onLogin={() => setCurrentPage("login")} />}
      {currentPage === "home" && (
        <HomePage
          onLogout={handleLogout}
          onNavigate={(page) => handleNavigate(page as PageType)}
          onOpenBerita={() => setCurrentPage("berita-tbc")}
        />
      )}
      {currentPage === "edukasi" && (
        <EdukasiPage
          onBack={() => setCurrentPage("home")}
          onNavigate={(page) => handleNavigate(page as PageType)}
          onOpenDiriSendiri={() => setCurrentPage("untuk-diri-sendiri")}
          onOpenKeluarga={() => setCurrentPage("untuk-keluarga")}
        />
      )}
      {currentPage === "jadwal" && (
        <MedicationReminderPage
          onNavigate={(page) => {
            if (page === "home") setCurrentPage("home")
            else if (page === "edukasi") setCurrentPage("edukasi")
          }}
        />
      )}
      {currentPage === "untuk-diri-sendiri" && <UntukDiriSendiriPage onBack={() => setCurrentPage("edukasi")} />}
      {currentPage === "untuk-keluarga" && <UntukKeluargaPage onBack={() => setCurrentPage("edukasi")} />}
      {currentPage === "berita-tbc" && <BeritaTBCPage onBack={() => setCurrentPage("home")} />}
    </>
  )
}
